CREATE TABLE journals (id uuid PRIMARY KEY,owner_id uuid NOT NULL,title_ciphertext bytea NOT NULL,description_ciphertext bytea,trip_id uuid,visibility varchar(16) NOT NULL DEFAULT 'PRIVATE' CHECK(visibility='PRIVATE'),permission_policy_ref varchar(128) NOT NULL,permission_policy_version integer NOT NULL CHECK(permission_policy_version>0),started_at timestamptz,ended_at timestamptz,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,deleted_at timestamptz,purge_after timestamptz,version integer NOT NULL CHECK(version>0),CHECK(ended_at IS NULL OR started_at IS NULL OR ended_at>=started_at));
CREATE INDEX journals_owner_page_idx ON journals(owner_id,created_at DESC,id DESC) WHERE deleted_at IS NULL;
CREATE INDEX journals_owner_trip_idx ON journals(owner_id,trip_id) WHERE deleted_at IS NULL;
CREATE TABLE journal_media_references (id uuid PRIMARY KEY,journal_id uuid NOT NULL REFERENCES journals(id) ON DELETE CASCADE,media_id uuid NOT NULL,media_kind varchar(16) NOT NULL CHECK(media_kind IN('VOICE','PHOTO','VIDEO')),caption_ciphertext bytea,position integer NOT NULL CHECK(position>=0),created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,deleted_at timestamptz,version integer NOT NULL CHECK(version>0));
CREATE UNIQUE INDEX journal_media_active_media_uq ON journal_media_references(journal_id,media_id) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX journal_media_active_position_uq ON journal_media_references(journal_id,position) WHERE deleted_at IS NULL;
CREATE TABLE journal_entries (id uuid PRIMARY KEY,journal_id uuid NOT NULL REFERENCES journals(id) ON DELETE CASCADE,position integer NOT NULL CHECK(position>=0),type varchar(32) NOT NULL CHECK(type IN('TEXT','VOICE_REFERENCE','PHOTO_REFERENCE','VIDEO_REFERENCE')),content_ciphertext bytea,media_reference_id uuid REFERENCES journal_media_references(id),occurred_at timestamptz NOT NULL,location_reference_ciphertext bytea,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,deleted_at timestamptz,version integer NOT NULL CHECK(version>0),CHECK((type='TEXT' AND content_ciphertext IS NOT NULL AND media_reference_id IS NULL) OR (type<>'TEXT' AND content_ciphertext IS NULL AND media_reference_id IS NOT NULL)));
CREATE UNIQUE INDEX journal_entries_active_position_uq ON journal_entries(journal_id,position) WHERE deleted_at IS NULL;
CREATE TABLE reflections (id uuid PRIMARY KEY,journal_id uuid NOT NULL REFERENCES journals(id) ON DELETE CASCADE,entry_id uuid REFERENCES journal_entries(id),text_ciphertext bytea NOT NULL,occurred_at timestamptz NOT NULL,position integer NOT NULL CHECK(position>=0),created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,deleted_at timestamptz,version integer NOT NULL CHECK(version>0));
CREATE UNIQUE INDEX reflections_active_position_uq ON reflections(journal_id,position) WHERE deleted_at IS NULL;
CREATE TABLE outbox_events(event_id uuid PRIMARY KEY,event_type varchar(128) NOT NULL,event_version integer NOT NULL,subject_type varchar(64) NOT NULL,subject_id uuid NOT NULL,subject_version integer NOT NULL,partition_key varchar(128) NOT NULL,payload jsonb NOT NULL,occurred_at timestamptz NOT NULL,available_at timestamptz NOT NULL,published_at timestamptz,attempt_count integer NOT NULL DEFAULT 0,last_error_code varchar(128),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX outbox_unpublished_idx ON outbox_events(available_at,event_id) WHERE published_at IS NULL;
CREATE TABLE inbox_events(event_id uuid NOT NULL,consumer_name varchar(128) NOT NULL,subject_id uuid,subject_version integer,processed_at timestamptz NOT NULL,PRIMARY KEY(event_id,consumer_name));
CREATE TABLE dead_letter_events(id uuid PRIMARY KEY,event_id uuid NOT NULL,event_type varchar(128) NOT NULL,payload_ciphertext bytea,last_error_code varchar(128) NOT NULL,attempt_count integer NOT NULL,next_retry_at timestamptz,resolved_at timestamptz,created_at timestamptz NOT NULL);
CREATE TABLE idempotency_records(environment varchar(32) NOT NULL,principal_id uuid NOT NULL,service varchar(64) NOT NULL,method varchar(16) NOT NULL,route_template varchar(256) NOT NULL,key_hash char(64) NOT NULL,request_hash char(64) NOT NULL,state varchar(16) NOT NULL,response_status integer,response_body_ciphertext bytea,created_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,PRIMARY KEY(environment,principal_id,service,method,route_template,key_hash));
CREATE TABLE legal_holds(id uuid PRIMARY KEY,authority_ref varchar(128) NOT NULL,reason_category varchar(64) NOT NULL,actor_id uuid NOT NULL,expires_at timestamptz,released_at timestamptz,released_by uuid,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,version integer NOT NULL CHECK(version>0));
CREATE TABLE legal_hold_resources(hold_id uuid NOT NULL REFERENCES legal_holds(id) ON DELETE CASCADE,resource_type varchar(64) NOT NULL,resource_id uuid NOT NULL,created_at timestamptz NOT NULL,PRIMARY KEY(hold_id,resource_type,resource_id));
